import json
o=[[0]*26 for _ in range(22)]
for r0,r1,c0,c1,border,color in [(1,6,3,11,1,4),(10,13,2,5,2,8),(9,16,11,21,3,5)]:
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if r in (r0,r1) or c in (c0,c1): o[r][c]=border
            elif (r+c)%2==0: o[r][c]=color
print(json.dumps(o))
